import { expect, test, type Page } from '@playwright/test'
import { readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'

function builtDemoHtml() {
  const outputDirectory = resolve('dist-demo')
  let html = readFileSync(resolve(outputDirectory, 'index.html'), 'utf8')

  html = html.replace(
    /<script type="module" crossorigin src="([^"]+)"><\/script>/,
    (_, source: string) => {
      const script = readFileSync(resolve(outputDirectory, source.slice(1)), 'utf8')
      return `<script type="module">${script}</script>`
    },
  )
  html = html.replace(/<link rel="stylesheet" crossorigin href="([^"]+)">/, (_, source: string) => {
    const css = readFileSync(resolve(outputDirectory, source.slice(1)), 'utf8')
    return `<style>${css}</style>`
  })

  return html
}

async function openDemo(page: Page) {
  await page.setContent(builtDemoHtml())
}

test('traps focus, closes with Escape, and restores the trigger', async ({ page }) => {
  await openDemo(page)
  const trigger = page.getByRole('button', { name: 'Edit profile' })
  await trigger.click()

  const dialog = page.getByRole('dialog', { name: 'Edit profile' })
  await expect(dialog).toBeVisible()
  await expect(dialog).toHaveAttribute('aria-modal', 'true')
  await expect(dialog).toHaveAccessibleDescription('Update your public information.')
  await expect(dialog.getByLabel('Name')).toBeFocused()

  await page.locator('a', { hasText: 'Background link' }).evaluate((element) => element.focus())
  await expect(dialog.getByLabel('Name')).toBeFocused()

  await page.keyboard.press('Shift+Tab')
  await expect(dialog.getByRole('button', { name: 'Close' })).toBeFocused()
  await page.keyboard.press('Tab')
  await expect(dialog.getByLabel('Name')).toBeFocused()

  await page.keyboard.press('Escape')
  await expect(dialog).toBeHidden()
  await expect(trigger).toBeFocused()
})

test('only the top nested dialog handles Escape and restores local focus', async ({ page }) => {
  await openDemo(page)
  await page.getByRole('button', { name: 'Edit profile' }).click()
  const parent = page.getByRole('dialog', { name: 'Edit profile' })
  const nestedTrigger = parent.getByRole('button', { name: 'Open permissions' })
  await nestedTrigger.click()

  const child = page.getByRole('dialog', { name: 'Permissions' })
  await expect(child).toBeVisible()
  await expect(child.getByRole('button', { name: 'Save permissions' })).toBeFocused()

  await page.keyboard.press('Escape')
  await expect(child).toBeHidden()
  await expect(parent).toBeVisible()
  await expect(nestedTrigger).toBeFocused()

  await page.keyboard.press('Escape')
  await expect(parent).toBeHidden()
})

test('clicking the top overlay dismisses without leaking product styling into the primitive', async ({
  page,
}) => {
  await openDemo(page)
  const trigger = page.getByRole('button', { name: 'Edit profile' })
  await trigger.click()

  await page.locator('.overlay').click({ position: { x: 4, y: 4 } })

  await expect(page.getByRole('dialog', { name: 'Edit profile' })).toBeHidden()
  await expect(trigger).toBeFocused()
})

import type { RefObject } from 'react'

type DialogLayer = {
  element: HTMLElement
}

type SavedIsolation = {
  ariaHidden: string | null
  inert: boolean
}

const layers: DialogLayer[] = []
const isolatedElements = new Map<HTMLElement, SavedIsolation>()

const focusableSelector = [
  'a[href]',
  'area[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  'summary',
  'iframe',
  '[contenteditable="true"]',
  '[tabindex]:not([tabindex="-1"])',
].join(',')

function isVisible(element: HTMLElement) {
  const style = window.getComputedStyle(element)
  return style.display !== 'none' && style.visibility !== 'hidden'
}

export function getFocusableElements(container: HTMLElement) {
  return Array.from(container.querySelectorAll<HTMLElement>(focusableSelector)).filter(
    (element) => !element.closest('[inert]') && isVisible(element),
  )
}

function restoreIsolation() {
  for (const [element, saved] of isolatedElements) {
    element.inert = saved.inert

    if (saved.ariaHidden === null) {
      element.removeAttribute('aria-hidden')
    } else {
      element.setAttribute('aria-hidden', saved.ariaHidden)
    }
  }
  isolatedElements.clear()
}

function isolate(element: HTMLElement) {
  if (isolatedElements.has(element)) return

  isolatedElements.set(element, {
    ariaHidden: element.getAttribute('aria-hidden'),
    inert: element.inert,
  })
  element.inert = true
  element.setAttribute('aria-hidden', 'true')
}

function syncIsolation() {
  restoreIsolation()

  const topLayer = layers.at(-1)?.element
  if (!topLayer?.isConnected) return

  let current: HTMLElement | null = topLayer
  while (current && current !== document.body) {
    const parentElement: HTMLElement | null = current.parentElement
    if (!parentElement) break

    for (const sibling of parentElement.children) {
      if (sibling !== current && sibling instanceof HTMLElement) isolate(sibling)
    }

    current = parentElement
  }
}

export function registerDialogLayer(element: HTMLElement) {
  const layer = { element }
  layers.push(layer)

  return {
    activate() {
      syncIsolation()
    },
    unregister() {
      const index = layers.indexOf(layer)
      if (index !== -1) layers.splice(index, 1)
      syncIsolation()
    },
  }
}

export function isTopDialogLayer(element: HTMLElement | null) {
  return Boolean(element && layers.at(-1)?.element === element)
}

type FocusScopeOptions = {
  contentRef: RefObject<HTMLElement | null>
  initialFocusRef?: RefObject<HTMLElement | null>
  onDismiss: () => void
  onEscapeKeyDown?: (event: KeyboardEvent) => void
}

export function mountFocusScope({
  contentRef,
  initialFocusRef,
  onDismiss,
  onEscapeKeyDown,
}: FocusScopeOptions) {
  const currentContent = contentRef.current
  if (!currentContent) return () => undefined
  const content: HTMLElement = currentContent

  const restoreTarget =
    document.activeElement instanceof HTMLElement ? document.activeElement : null
  const layer = registerDialogLayer(content)
  const initialFocus = initialFocusRef?.current ?? getFocusableElements(content)[0] ?? content
  let lastFocusedInside: HTMLElement = initialFocus

  initialFocus.focus({ preventScroll: true })
  layer.activate()

  function handleFocusIn(event: FocusEvent) {
    if (!isTopDialogLayer(content)) return

    const target = event.target
    if (target instanceof HTMLElement && content.contains(target)) {
      lastFocusedInside = target
      return
    }

    const fallback =
      (lastFocusedInside.isConnected && lastFocusedInside) ||
      getFocusableElements(content)[0] ||
      content
    fallback.focus({ preventScroll: true })
  }

  function handleKeyDown(event: KeyboardEvent) {
    if (!isTopDialogLayer(content)) return

    if (event.key === 'Escape') {
      onEscapeKeyDown?.(event)
      if (event.defaultPrevented) return

      event.preventDefault()
      event.stopPropagation()
      onDismiss()
      return
    }

    if (event.key !== 'Tab' || event.defaultPrevented) return

    const focusableElements = getFocusableElements(content)
    if (focusableElements.length === 0) {
      event.preventDefault()
      content.focus({ preventScroll: true })
      return
    }

    const first = focusableElements[0]
    const last = focusableElements.at(-1)!
    const activeElement = document.activeElement

    if (!content.contains(activeElement)) {
      event.preventDefault()
      ;(event.shiftKey ? last : first).focus({ preventScroll: true })
    } else if (event.shiftKey && activeElement === first) {
      event.preventDefault()
      last.focus({ preventScroll: true })
    } else if (!event.shiftKey && activeElement === last) {
      event.preventDefault()
      first.focus({ preventScroll: true })
    }
  }

  document.addEventListener('focusin', handleFocusIn)
  document.addEventListener('keydown', handleKeyDown, true)

  return () => {
    document.removeEventListener('focusin', handleFocusIn)
    document.removeEventListener('keydown', handleKeyDown, true)
    layer.unregister()

    if (restoreTarget?.isConnected) restoreTarget.focus({ preventScroll: true })
  }
}

import {
  createContext,
  forwardRef,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type MouseEvent as ReactMouseEvent,
  type ReactNode,
  type Ref,
  type RefObject,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { createPortal } from 'react-dom'

import { isTopDialogLayer, mountFocusScope } from './focusScope'

export type DialogOpenChangeReason =
  | 'trigger'
  | 'close-button'
  | 'escape-key'
  | 'outside-interaction'

export type DialogOpenChangeDetails = { reason: DialogOpenChangeReason }

type DialogRootBaseProps = {
  children: ReactNode
  onOpenChange?: (open: boolean, details: DialogOpenChangeDetails) => void
}

export type DialogRootProps = DialogRootBaseProps &
  ({ defaultOpen?: boolean; open?: never } | { defaultOpen?: never; open: boolean })

type DialogContextValue = {
  contentId: string
  contentRef: RefObject<HTMLDivElement | null>
  descriptionId: string
  open: boolean
  setOpen: (open: boolean, reason: DialogOpenChangeReason) => void
  titleId: string
  triggerRef: RefObject<HTMLButtonElement | null>
}

const DialogContext = createContext<DialogContextValue | null>(null)
const useIsomorphicLayoutEffect = typeof document === 'undefined' ? useEffect : useLayoutEffect

function useDialogContext(componentName: string) {
  const context = useContext(DialogContext)
  if (!context) throw new Error(`${componentName} must be rendered inside Dialog.Root.`)
  return context
}

function assignRef<T>(ref: Ref<T> | undefined, value: T | null) {
  if (typeof ref === 'function') ref(value)
  else if (ref) ref.current = value
}

function useComposedRef<T>(...refs: Array<Ref<T> | undefined>) {
  return useCallback((value: T | null) => {
    for (const ref of refs) assignRef(ref, value)
  }, refs)
}

export function DialogRoot({
  children,
  defaultOpen = false,
  onOpenChange,
  open: controlledOpen,
}: DialogRootProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isControlled = controlledOpen !== undefined
  const open = isControlled ? controlledOpen : uncontrolledOpen
  const contentId = useId()
  const titleId = useId()
  const descriptionId = useId()
  const triggerRef = useRef<HTMLButtonElement>(null)
  const contentRef = useRef<HTMLDivElement>(null)

  const setOpen = useCallback(
    (nextOpen: boolean, reason: DialogOpenChangeReason) => {
      if (!isControlled) setUncontrolledOpen(nextOpen)
      if (nextOpen !== open) onOpenChange?.(nextOpen, { reason })
    },
    [isControlled, onOpenChange, open],
  )

  const value = useMemo<DialogContextValue>(
    () => ({
      contentId,
      contentRef,
      descriptionId,
      open,
      setOpen,
      titleId,
      triggerRef,
    }),
    [contentId, descriptionId, open, setOpen, titleId],
  )

  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

export type DialogTriggerProps = ButtonHTMLAttributes<HTMLButtonElement>

export const DialogTrigger = forwardRef<HTMLButtonElement, DialogTriggerProps>(
  function DialogTrigger({ onClick, type = 'button', ...props }, forwardedRef) {
    const context = useDialogContext('Dialog.Trigger')
    const ref = useComposedRef(forwardedRef, context.triggerRef)

    function handleClick(event: ReactMouseEvent<HTMLButtonElement>) {
      onClick?.(event)
      if (!event.defaultPrevented) context.setOpen(true, 'trigger')
    }

    return (
      <button
        {...props}
        ref={ref}
        type={type}
        aria-controls={context.contentId}
        aria-expanded={context.open}
        aria-haspopup="dialog"
        data-state={context.open ? 'open' : 'closed'}
        onClick={handleClick}
      />
    )
  },
)

export type DialogPortalProps = {
  children: ReactNode
  container?: Element | DocumentFragment | null
}

export function DialogPortal({ children, container }: DialogPortalProps) {
  const context = useDialogContext('Dialog.Portal')
  const [mounted, setMounted] = useState(false)

  useEffect(() => setMounted(true), [])

  if (!context.open || !mounted) return null
  return createPortal(children, container ?? document.body)
}

export type DialogOverlayProps = HTMLAttributes<HTMLDivElement>

export const DialogOverlay = forwardRef<HTMLDivElement, DialogOverlayProps>(
  function DialogOverlay({ onClick, ...props }, forwardedRef) {
    const context = useDialogContext('Dialog.Overlay')

    function handleClick(event: ReactMouseEvent<HTMLDivElement>) {
      onClick?.(event)
      if (
        !event.defaultPrevented &&
        event.target === event.currentTarget &&
        isTopDialogLayer(context.contentRef.current)
      ) {
        context.setOpen(false, 'outside-interaction')
      }
    }

    if (!context.open) return null
    return <div {...props} ref={forwardedRef} data-state="open" onClick={handleClick} />
  },
)

export type DialogContentProps = Omit<HTMLAttributes<HTMLDivElement>, 'aria-label'> & {
  'aria-label'?: string
  initialFocusRef?: RefObject<HTMLElement | null>
  onEscapeKeyDown?: (event: KeyboardEvent) => void
}

export const DialogContent = forwardRef<HTMLDivElement, DialogContentProps>(
  function DialogContent(
    {
      'aria-describedby': ariaDescribedBy,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      initialFocusRef,
      onEscapeKeyDown,
      tabIndex = -1,
      ...props
    },
    forwardedRef,
  ) {
    const context = useDialogContext('Dialog.Content')
    const ref = useComposedRef(forwardedRef, context.contentRef)

    useIsomorphicLayoutEffect(() => {
      if (!context.open) return

      return mountFocusScope({
        contentRef: context.contentRef,
        initialFocusRef,
        onDismiss: () => context.setOpen(false, 'escape-key'),
        onEscapeKeyDown,
      })
    }, [context.contentRef, context.open, context.setOpen, initialFocusRef, onEscapeKeyDown])

    if (!context.open) return null
    return (
      <div
        {...props}
        ref={ref}
        id={context.contentId}
        role="dialog"
        aria-describedby={ariaDescribedBy ?? context.descriptionId}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabel ? undefined : (ariaLabelledBy ?? context.titleId)}
        aria-modal="true"
        data-state="open"
        tabIndex={tabIndex}
      />
    )
  },
)

export type DialogTitleProps = Omit<HTMLAttributes<HTMLHeadingElement>, 'id'>

export const DialogTitle = forwardRef<HTMLHeadingElement, DialogTitleProps>(
  function DialogTitle(props, forwardedRef) {
    const context = useDialogContext('Dialog.Title')
    return <h2 {...props} ref={forwardedRef} id={context.titleId} />
  },
)

export type DialogDescriptionProps = Omit<HTMLAttributes<HTMLParagraphElement>, 'id'>

export const DialogDescription = forwardRef<HTMLParagraphElement, DialogDescriptionProps>(
  function DialogDescription(props, forwardedRef) {
    const context = useDialogContext('Dialog.Description')
    return <p {...props} ref={forwardedRef} id={context.descriptionId} />
  },
)

export type DialogCloseProps = ButtonHTMLAttributes<HTMLButtonElement>

export const DialogClose = forwardRef<HTMLButtonElement, DialogCloseProps>(
  function DialogClose({ onClick, type = 'button', ...props }, forwardedRef) {
    const context = useDialogContext('Dialog.Close')

    function handleClick(event: ReactMouseEvent<HTMLButtonElement>) {
      onClick?.(event)
      if (!event.defaultPrevented) context.setOpen(false, 'close-button')
    }

    return <button {...props} ref={forwardedRef} type={type} onClick={handleClick} />
  },
)

export const Dialog = {
  Root: DialogRoot,
  Trigger: DialogTrigger,
  Portal: DialogPortal,
  Overlay: DialogOverlay,
  Content: DialogContent,
  Title: DialogTitle,
  Description: DialogDescription,
  Close: DialogClose,
} as const

